/*
 * backend_mem.c - a fake in-memory directory tree (used by the read-only prototype server)
 *
 * Directory layout (the smoke test tests/m0_smoke.sh checks against this):
 *   /hello.txt          fixed text
 *   /big.bin            1 MiB, generated by openmacfuse_mem_big_byte(), used to verify data stitched together from several READs
 *   /<CJK name>.txt     a UTF-8 file name (three Chinese characters, see openmacfuse_backend_mem_init)
 *   /sub/inner.txt
 *   /link -> hello.txt  symbolic link
 *   /many/f00000 ... f02999   3000 empty files, used to verify READDIR paging (resuming from a cookie)
 *
 * Copyright 2026 The OpenMacFUSE Authors
 * SPDX-License-Identifier: MIT
 */
#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>

#include "backend.h"

#define MEM_BIG_SIZE	(1024 * 1024)
#define MEM_MANY_COUNT	3000

struct mem_node {
	openmacfuse_ino_t	ino;
	openmacfuse_ino_t	parent;
	char		*name;
	uint32_t	mode;
	const char	*data;		/* fixed contents of a regular file (except big.bin, which is generated) */
	uint64_t	size;
	const char	*target;	/* symlink target */
	openmacfuse_ino_t	*kids;		/* children of a directory */
	uint32_t	nkids;
	uint32_t	capkids;
	int		is_big;
};

struct mem_fs {
	struct mem_node	*nodes;		/* index is the inode number (0 unused) */
	uint32_t	n;
	uint32_t	cap;
	struct timespec	t0;
	uint32_t	uid;
	uint32_t	gid;
};

/* Byte off of big.bin: a simple reproducible pseudo-random value; the test script checks it with the same formula */
static uint8_t mem_big_byte(uint64_t off)
{
	return (uint8_t)((off * 31u + (off >> 8)) & 0xff);
}

static struct mem_node *node(struct mem_fs *fs, openmacfuse_ino_t ino)
{
	if (ino == 0 || ino >= fs->n)
		return NULL;
	return &fs->nodes[ino];
}

static openmacfuse_ino_t add_node(struct mem_fs *fs, openmacfuse_ino_t parent,
			   const char *name, uint32_t mode)
{
	struct mem_node *nd, *p;

	if (fs->n == fs->cap) {
		uint32_t nc = fs->cap ? fs->cap * 2 : 64;
		struct mem_node *nn = realloc(fs->nodes, nc * sizeof(*nn));
		if (!nn)
			return 0;
		fs->nodes = nn;
		fs->cap = nc;
	}
	nd = &fs->nodes[fs->n];
	memset(nd, 0, sizeof(*nd));
	nd->ino = fs->n;
	nd->parent = parent ? parent : nd->ino;
	nd->name = strdup(name);
	nd->mode = mode;
	fs->n++;

	if (parent) {
		p = &fs->nodes[parent];
		if (p->nkids == p->capkids) {
			uint32_t nc = p->capkids ? p->capkids * 2 : 8;
			openmacfuse_ino_t *nk = realloc(p->kids, nc * sizeof(*nk));
			if (!nk)
				return 0;
			p->kids = nk;
			p->capkids = nc;
		}
		p->kids[p->nkids++] = nd->ino;
	}
	return nd->ino;
}

static openmacfuse_ino_t mem_root(void *bctx)
{
	(void)bctx;
	return 1;
}

static int mem_getattr(void *bctx, openmacfuse_ino_t ino, struct openmacfuse_attr *st,
		       unsigned want)
{
	struct mem_fs *fs = bctx;
	struct mem_node *nd = node(fs, ino);

	if (!nd)
		return -ENOENT;
	memset(st, 0, sizeof(*st));
	st->ino = ino;
	st->mode = nd->mode;
	st->nlink = S_ISDIR(nd->mode) ? 2 : 1;
	st->uid = fs->uid;
	st->gid = fs->gid;
	if (S_ISDIR(nd->mode))
		st->size = 4096;
	else if (S_ISLNK(nd->mode))
		st->size = strlen(nd->target);
	else
		st->size = nd->size;
	st->used = (st->size + 4095) & ~4095ull;
	st->atime = st->mtime = st->ctime = st->crtime = fs->t0;
	st->change = 1;		/* read-only fake tree, contents never change */
	return 0;
}

static int mem_lookup(void *bctx, openmacfuse_ino_t dir, const char *name,
		      openmacfuse_ino_t *out)
{
	struct mem_fs *fs = bctx;
	struct mem_node *d = node(fs, dir);
	uint32_t i;

	if (!d)
		return -ENOENT;
	if (!S_ISDIR(d->mode))
		return -ENOTDIR;
	for (i = 0; i < d->nkids; i++) {
		if (strcmp(fs->nodes[d->kids[i]].name, name) == 0) {
			*out = d->kids[i];
			return 0;
		}
	}
	return -ENOENT;
}

static int mem_lookupp(void *bctx, openmacfuse_ino_t dir, openmacfuse_ino_t *out)
{
	struct mem_fs *fs = bctx;
	struct mem_node *d = node(fs, dir);

	if (!d)
		return -ENOENT;
	if (d->parent == d->ino)
		return -ENOENT;
	*out = d->parent;
	return 0;
}

static int mem_readdir(void *bctx, openmacfuse_ino_t dir, uint64_t pos,
		       uint64_t *verf, unsigned want, openmacfuse_fill_fn fill,
		       void *arg, int *eof)
{
	struct mem_fs *fs = bctx;
	struct mem_node *d = node(fs, dir);
	uint64_t i;

	(void)want;
	*eof = 0;
	/* The fake tree never changes: the verifier is fixed, derived from the directory inode number */
	if (pos && *verf != (uint64_t)dir + 1)
		return -OPENMACFUSE_E_NOT_SAME;
	*verf = (uint64_t)dir + 1;
	if (!d)
		return -ENOENT;
	if (!S_ISDIR(d->mode))
		return -ENOTDIR;
	/* The position is simply the child index: naturally linear and resumable */
	for (i = pos; i < d->nkids; i++) {
		struct openmacfuse_dirent de = {
			.name = fs->nodes[d->kids[i]].name,
			.ino = d->kids[i],
			.pos = i + 1,
			.attr = NULL,
		};
		if (fill(arg, &de))
			return 0;
	}
	*eof = 1;
	return 0;
}

static int mem_open(void *bctx, openmacfuse_ino_t ino, int flags, uint64_t *fh)
{
	struct mem_fs *fs = bctx;
	struct mem_node *nd = node(fs, ino);

	(void)flags;
	if (!nd)
		return -ENOENT;
	if (S_ISDIR(nd->mode))
		return -EISDIR;
	*fh = ino;
	return 0;
}

static int mem_release(void *bctx, openmacfuse_ino_t ino, uint64_t fh)
{
	(void)bctx; (void)ino; (void)fh;
	return 0;
}

static int mem_read(void *bctx, openmacfuse_ino_t ino, uint64_t fh, void *buf,
		    uint32_t size, uint64_t off)
{
	struct mem_fs *fs = bctx;
	struct mem_node *nd = node(fs, ino);
	uint64_t n, i;
	uint8_t *p = buf;

	(void)fh;
	if (!nd)
		return -ENOENT;
	if (S_ISDIR(nd->mode))
		return -EISDIR;
	if (off >= nd->size)
		return 0;
	n = nd->size - off;
	if (n > size)
		n = size;
	if (nd->is_big) {
		for (i = 0; i < n; i++)
			p[i] = mem_big_byte(off + i);
	} else {
		memcpy(p, nd->data + off, n);
	}
	return (int)n;
}

static int mem_readlink(void *bctx, openmacfuse_ino_t ino, char *buf, size_t size)
{
	struct mem_fs *fs = bctx;
	struct mem_node *nd = node(fs, ino);

	if (!nd)
		return -ENOENT;
	if (!S_ISLNK(nd->mode))
		return -EINVAL;
	snprintf(buf, size, "%s", nd->target);
	return 0;
}

static int mem_statfs(void *bctx, struct openmacfuse_statfs *sf)
{
	struct mem_fs *fs = bctx;

	memset(sf, 0, sizeof(*sf));
	sf->bsize = 4096;
	sf->blocks = 262144;		/* pretend 1 GiB */
	sf->bfree = sf->bavail = 131072;
	sf->files = 100000;
	sf->ffree = 100000 - fs->n;
	sf->namemax = 255;
	return 0;
}

static int mem_resolve(void *bctx, openmacfuse_ino_t ino, const openmacfuse_ino_t *anc,
		       int nanc)
{
	(void)anc; (void)nanc;
	return node(bctx, ino) ? 0 : -ESTALE;
}

static const struct openmacfuse_backend_ops mem_ops = {
	.resolve	= mem_resolve,
	.root		= mem_root,
	.getattr	= mem_getattr,
	.lookup		= mem_lookup,
	.lookupp	= mem_lookupp,
	.readdir	= mem_readdir,
	.open		= mem_open,
	.release	= mem_release,
	.read		= mem_read,
	.readlink	= mem_readlink,
	.statfs		= mem_statfs,
};

static void add_file(struct mem_fs *fs, openmacfuse_ino_t dir, const char *name,
		     const char *text)
{
	openmacfuse_ino_t i = add_node(fs, dir, name, S_IFREG | 0644);

	if (!i)
		return;
	fs->nodes[i].data = text;
	fs->nodes[i].size = strlen(text);
}

int openmacfuse_backend_mem_init(struct openmacfuse_backend *be)
{
	struct mem_fs *fs = calloc(1, sizeof(*fs));
	openmacfuse_ino_t root, sub, many, big, lnk;
	char nm[32];
	int i;

	if (!fs)
		return -ENOMEM;
	clock_gettime(CLOCK_REALTIME, &fs->t0);
	fs->uid = getuid();
	fs->gid = getgid();

	add_node(fs, 0, "", 0);			/* occupy number 0, never exposed */
	root = add_node(fs, 0, "", S_IFDIR | 0755);

	add_file(fs, root, "hello.txt", "Hello from openmacfuse M0\n");
	big = add_node(fs, root, "big.bin", S_IFREG | 0644);
	fs->nodes[big].is_big = 1;
	fs->nodes[big].size = MEM_BIG_SIZE;
	/* UTF-8 file name and contents (escaped bytes; the smoke test reads this file back by name) */
	add_file(fs, root, "\xe4\xb8\xad\xe6\x96\x87\xe5\x90\x8d.txt", "\xe4\xb8\xad\xe6\x96\x87\xe5\x86\x85\xe5\xae\xb9\n");
	sub = add_node(fs, root, "sub", S_IFDIR | 0755);
	add_file(fs, sub, "inner.txt", "inner file\n");
	lnk = add_node(fs, root, "link", S_IFLNK | 0755);
	fs->nodes[lnk].target = "hello.txt";
	many = add_node(fs, root, "many", S_IFDIR | 0755);
	for (i = 0; i < MEM_MANY_COUNT; i++) {
		snprintf(nm, sizeof(nm), "f%05d", i);
		add_file(fs, many, nm, "");
	}

	be->ops = &mem_ops;
	be->ctx = fs;
	be->readonly = 1;
	return 0;
}
